-- Additive: preserve all record/movement IDs, amounts, allocations and closed history.
-- Historical defaults/snapshots remain NULL (unreviewed). No backfill.
-- Hand-corrected: generated table rebuild selected nonexistent new columns.
ALTER TABLE `accounts` ADD `default_tax_percentage_bps` integer CONSTRAINT `accounts_tax_percentage_check` CHECK ("accounts"."default_tax_percentage_bps" IS NULL OR (typeof("accounts"."default_tax_percentage_bps") = 'integer' AND "accounts"."default_tax_percentage_bps" BETWEEN 0 AND 10000 AND "accounts"."type" IS 5));--> statement-breakpoint
ALTER TABLE `accounts` ADD `default_tax_treatment` text CONSTRAINT `accounts_tax_treatment_check` CHECK ("accounts"."default_tax_treatment" IS NULL OR ("accounts"."type" IS 5 AND "accounts"."default_tax_treatment" IN ('ordinary_deductible', 'partial', 'non_deductible', 'capital_expenditure', 'requires_review')));--> statement-breakpoint
ALTER TABLE `ledger_movements` ADD `tax_classification` text CONSTRAINT `movements_tax_json_check` CHECK ("ledger_movements"."tax_classification" IS NULL OR CASE WHEN json_valid("ledger_movements"."tax_classification") THEN coalesce(json_type("ledger_movements"."tax_classification", '$.percentageBps') IN ('null', 'integer') AND (json_extract("ledger_movements"."tax_classification", '$.percentageBps') IS NULL OR json_extract("ledger_movements"."tax_classification", '$.percentageBps') BETWEEN 0 AND 10000) AND json_extract("ledger_movements"."tax_classification", '$.source') IN ('account_default', 'override', 'unreviewed') AND json_extract("ledger_movements"."tax_classification", '$.treatment') IN ('ordinary_deductible', 'partial', 'non_deductible', 'capital_expenditure', 'requires_review'), 0) ELSE 0 END);
